function activate(id) {
  const control = controls.find(c => c.id === id);
  if (!control) return;

  if (control.type === "toggle") {
    control.active = !control.active;
  } else if (control.type === "radio") {
    controls.forEach(c => {
      if (c.groupId === control.groupId) c.active = c.id === control.id;
    });
  } else if (control.type === "transient") {
    control.active = true;
    setTimeout(() => {
      control.active = false;
      renderCanvas();
    }, 180);
  }
  renderCanvas();
}

