const puppeteer = require("puppeteer-core");

(async () => {
  const browser = await puppeteer.launch({
    executablePath: "/usr/bin/google-chrome",
    headless: "new",
    args: ["--no-sandbox", "--disable-dev-shm-usage"],
  });
  const page = await browser.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  page.on("console", (msg) => {
    if (msg.type() === "error") errors.push("console.error: " + msg.text());
  });

  await page.goto("http://127.0.0.1:8934/index.html", { waitUntil: "networkidle0" });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: "networkidle0" });

  // --- Add a toggle control named "Record" with key "r" ---
  await page.click("#new-name");
  await page.type("#new-name", "Record");
  await page.click("#new-key");
  await page.keyboard.press("r");
  await page.click("#add-button");

  let tileCount = await page.$$eval(".tile", (els) => els.length);
  console.log("After adding toggle, tile count:", tileCount);

  // --- Add a transient control named "Snap" with key "s" ---
  await page.select("#new-type", "transient");
  await page.click("#new-name");
  await page.type("#new-name", "Snap");
  await page.click("#new-key");
  await page.keyboard.press("s");
  await page.click("#add-button");

  // --- Add two radio options in a new group "Angle" ---
  await page.select("#new-type", "radio");
  await page.click("#new-group-name");
  await page.type("#new-group-name", "Angle");
  await page.click("#new-name");
  await page.type("#new-name", "Front");
  await page.click("#new-key");
  await page.keyboard.press("1");
  await page.click("#add-button");

  await page.select("#new-type", "radio");
  // group select should now default to the existing "Angle" group
  await page.click("#new-name");
  await page.type("#new-name", "Side");
  await page.click("#new-key");
  await page.keyboard.press("2");
  await page.click("#add-button");

  tileCount = await page.$$eval(".tile", (els) => els.length);
  console.log("After adding all 4 controls, tile count:", tileCount);

  const listRows = await page.$$eval(".control-row", (els) => els.map((e) => e.textContent.trim()));
  console.log("Sidebar control rows:", listRows);

  // --- Drag the "Record" tile in setup mode ---
  const recordTile = await page.evaluateHandle(() => {
    return [...document.querySelectorAll(".tile")].find((t) => t.textContent.includes("Record"));
  });
  const box = await recordTile.asElement().boundingBox();
  const startX = box.x + box.width / 2;
  const startY = box.y + box.height / 2;
  await page.mouse.move(startX, startY);
  await page.mouse.down();
  await page.mouse.move(startX + 120, startY + 80, { steps: 10 });
  await page.mouse.up();

  const newLeft = await page.evaluate(() => {
    const t = [...document.querySelectorAll(".tile")].find((el) => el.textContent.includes("Record"));
    return t.style.left;
  });
