    const front = [...document.querySelectorAll(".tile")].find((el) => el.textContent.includes("Front"));
    const side = [...document.querySelectorAll(".tile")].find((el) => el.textContent.includes("Side"));
    return { front: front.classList.contains("active"), side: side.classList.contains("active") };
  });
  console.log("After clicking Side:", radioState);

