function mechanicalDialog() {
  return Array.from(document.querySelectorAll('.ngdialog, .modal.in, [role="dialog"]')).find((dialog) => {
    const style = getComputedStyle(dialog);
    if (style.display === "none" || style.visibility === "hidden" || dialog.offsetHeight <= 0) return false;
    return /mechanical\s+information/i.test(textOf(dialog.querySelector(".modal-header, h4") || dialog));
  }) || null;
}

async function openMechanicalEditor() {
  const alreadyOpen = mechanicalDialog();
  if (alreadyOpen) return { root: alreadyOpen };

  await waitForNetworkIdle();
  const addButton = await waitFor(
    () => Array.from(document.querySelectorAll("button, a")).find((button) => {
      if (!visibleElement(button) || button.disabled) return false;
      const click = button.getAttribute("ng-click") || "";
      return /openSOWMechanicalPopup/i.test(click) && !/row\.entity/i.test(click);
    }) || null,
    8000
  );
  if (!addButton) {
    console.warn("Equipment fill: could not find enabled Add Equipment button.");
    return null;
  }

  addButton.click();
  await waitForNetworkIdle();
  const dialog = await waitFor(() => mechanicalDialog(), 8000);
  if (!dialog) {
    console.warn("Equipment fill: Mechanical Information dialog did not appear after clicking Add.");
    return null;
  }
  await wait(500);
  return { root: dialog };
}

function fillMechanicalTextField(root, id, value) {
  if (!String(value ?? "").trim()) return;

  const field = elementByIdWithin(root, id);
  if (!field) return;

  setNativeValue(field, value);
  field.dispatchEvent(new Event("input", { bubbles: true }));
  field.dispatchEvent(new Event("change", { bubbles: true }));
  setAngularViewValue(field, value);
}

// selectOptionByText's fuzzy fallback (substring containment) can match the wrong
// option when one option's label is itself a substring of another's (e.g. "EER" is
// contained in "SEER"), so an exact label/text match must always win first.
function selectMechanicalOptionByText(select, value) {
  if (!select || !value) return false;

  const options = Array.from(select.options || []).filter((option) => option.value);
  const expected = normalizeComparableText(value);
  const exact = options.find((option) => {
    const text = normalizeComparableText(option.text || textOf(option));
    const label = normalizeComparableText(option.getAttribute?.("label") || "");
    return text === expected || label === expected;
  });

  const option = exact || options.find((candidate) => optionMatchesText(candidate, value));
  if (!option) return false;

  setAngularSelectValue(select, option);
  return true;
}

async function fillMechanicalEditorFields(editor, item, row) {
  const root = editor.root;
  const value = (patterns) => rowValueByHeader(row, patterns);

  const subcategory = elementByIdWithin(root, "ddlsubcat");
  const subcategoryValue = value([/subcategory/i]);
  if (subcategory && subcategoryValue) {
    if (!selectMechanicalOptionByText(subcategory, subcategoryValue)) {
      console.warn("Equipment fill: could not find Subcategory option:", subcategoryValue);
      return false;
    }
    await waitForNetworkIdle();
  }

  fillMechanicalTextField(root, "txtItem", value([/^item\s*name$/i, /^item$/i]));
  fillMechanicalTextField(root, "txtItemText", value([/item.*description/i]));
  fillMechanicalTextField(root, "txtLocation", value([/^location$/i]));
  fillMechanicalTextField(root, "txtNumberOfItems", value([/number.*items/i]));
  fillMechanicalTextField(root, "txtCapacityNumber", value([/capacity.*number/i]));

  const capacityUnits = elementByIdWithin(root, "ddlCapacity");
  const capacityUnitsValue = value([/capacity.*units?/i]);
  if (capacityUnits && capacityUnitsValue) selectMechanicalOptionByText(capacityUnits, capacityUnitsValue);

  fillMechanicalTextField(root, "txtEquipmentEfficiency", value([/equipment.*efficiency/i]));

  const efficiencyUnits = elementByIdWithin(root, "ddlEquipmentUnits");
  const efficiencyUnitsValue = value([/^efficiency\s*units?/i]);
  if (efficiencyUnits && efficiencyUnitsValue) selectMechanicalOptionByText(efficiencyUnits, efficiencyUnitsValue);

  fillMechanicalTextField(root, "txtManufacturerName", value([/manufacturer/i]));

  const cocValue = value([/certificate.*compliance/i, /coc.*needed/i]);
  if (cocValue) {
    const desiredBoolean = booleanValue(cocValue);
    const radios = Array.from(root.querySelectorAll('input[type="radio"][name="rdCertificateofComplianceNeeded"]'));
    const target = radios.find((radio) => radioOptionMatchesValue(radio, desiredBoolean));
    if (target && !target.checked) target.click();
  }

  fillMechanicalTextField(root, "txtModelName", value([/model\s*name/i]));
  fillMechanicalTextField(root, "txtCertificationNumberForListing", value([/serial\s*number/i]));

  return true;
}

async function applyMechanicalRows(item) {
  // A bulk item (stored from the empty grid canvas) applies every row of the pasted
  // sub-table. A single copied row falls back to whatever fields the grid exposed as
  // visible columns (cellData), reusing the same header-matching fill logic.
  const rows = item.bulkTable
    ? embeddedSubTableRowsForItem(item)
    : [item.cellData && typeof item.cellData === "object" ? item.cellData : {}];
  if (!rows.length) {
    console.log("Helper Toolkit: no equipment rows to apply, skipping:", item);
    return true;
  }

  let applied = 0;
  for (const row of rows) {
    const grid = getElement(item);
    if (grid && embeddedSubTableRowExistsInGrid(grid, row)) {
      console.log("Helper Toolkit: equipment row already present, skipping:", embeddedSubTableRowIdentityValue(row));
      continue;
    }

    const editor = await openMechanicalEditor(item);
    if (!editor) return false;

    const filled = await fillMechanicalEditorFields(editor, item, row);
    if (!filled) return false;

    const saveButton = findTableEditorSaveButton(editor);
    if (!saveButton) {
      console.warn("Equipment fill: could not find Add/Update button in Mechanical Information dialog.");
      return false;
    }

    // Equipment Add/Update does not show an OK confirmation dialog; proceed as
    // soon as the grid has refreshed.
    saveButton.click();
    await waitForNetworkIdle();
    await wait(500);
    applied += 1;
  }

  console.log(`Helper Toolkit: applied ${applied} equipment row(s).`);
  return true;
}

const mechanicalTableRowConfig = {
  label: "Equipment",
  category: "",
  kind: "equipment",
  openEditor: openMechanicalEditor,
  fillEditor: fillMechanicalEditorFields,
  applyRows: applyMechanicalRows,
  useCellTextSignature: true,
};

function rowDataForGridConfig(config, rowEntity) {
  if (!config?.storeRowData) return undefined;
  if (!rowEntity || typeof rowEntity !== "object") return undefined;

  if (Array.isArray(config.storeRowData)) {
    return config.storeRowData.reduce((data, key) => {
      if (rowEntity[key] !== undefined) data[key] = serializableClone(rowEntity[key]);
      return data;
    }, {});
  }

  return serializableClone(rowEntity);
}

