async function applyGenericTableRow(item) {
  const config = isFloorStoredItem(item) ? floorTableRowConfig : tableRowConfigForGrid(item.gridName, getElement(item));
  if (!config) {
    console.warn("No table row config found for grid:", item.gridName);
    return false;
  }

  if (config.applyRows) return config.applyRows(item);

  const editor = await config.openEditor(item);
  if (!editor) return false;

  const filled = await config.fillEditor(editor, item);
  if (!filled) return false;

  const saveButton = findTableEditorSaveButton(editor);
  if (!saveButton) {
    console.warn("Could not find save/update button in editor.", { rowSignature: item.rowSignature });
    return false;
  }

  saveButton.click();
  await clickNotificationOkIfPresent(10000);
  await waitFor(() => storedValueStatus(item) === "match", 10000);
  return true;
}

