async function applyFloorRows(item) {
  const tableRows = item.bulkTable ? embeddedSubTableRowsForItem(item) : tableDataRowsForItem(item);
  const floorRows = tableRows.length
    ? tableRows.map((row) => ({
        floor: floorValueFromTableRow(row),
        row,
      }))
    : floorValuesForItem(item).map((floor) => ({ floor, row: null }));

  if (!floorRows.length) {
    console.log("Helper Toolkit: no floor values to apply, skipping:", item);
    return true;
  }

  let applied = 0;
  for (const { floor, row } of floorRows) {
    if (!String(floor ?? "").trim()) {
      console.warn("Helper Toolkit: skipping table-driven floor row with no matching floor/location value.", row);
      continue;
    }
    if (floorValueExistsInGrid(item, floor)) {
      console.log("Helper Toolkit: floor row already present, skipping:", floor);
      continue;
    }

    const editor = await openFloorEditor(item);
    if (!editor) return false;

    const filled = await fillFloorEditorFields(editor, item, floor, row);
    if (!filled) return false;

    const saveButton = findTableEditorSaveButton(editor);
    if (!saveButton) {
      console.warn("Floor fill: could not find Add/Save button in Work on Floors dialog.");
      return false;
    }

    // Work on Floors Add/Update does not show an OK confirmation dialog; proceed
    // as soon as the grid has refreshed.
    saveButton.click();
    await waitForNetworkIdle();
    await wait(500);
    applied += 1;
  }

  console.log(`Helper Toolkit: applied ${applied} floor row(s).`);
  await waitFor(() => storedValueStatus(item) === "match", 10000);
  return true;
}

