async function openFloorEditor() {
  const alreadyOpen = floorDialog();
  if (alreadyOpen) return { root: alreadyOpen };

  await waitForNetworkIdle();
  const addButton = await waitFor(
    () => Array.from(document.querySelectorAll("button, a")).find((button) => {
      if (!visibleElement(button) || button.disabled) return false;
      const click = button.getAttribute("ng-click") || "";
      const label = textOf(button);
      if (/row\.entity/i.test(click)) return false;
      return /floor/i.test(click + " " + label) && /\badd\b/i.test(label);
    }) || null,
    8000
  );
  if (!addButton) {
    console.warn("Floor fill: could not find enabled Add floor button.");
    return null;
  }

  addButton.click();
  await waitForNetworkIdle();
  const dialog = await waitFor(() => floorDialog(), 8000);
  if (!dialog) {
    console.warn("Floor fill: Work on Floors dialog did not appear after clicking Add.");
    return null;
  }
  await wait(500);
  return { root: dialog };
}

function optionMatchesText(option, value) {
  const expected = normalizeSelectionText(value);
  const text = normalizeSelectionText(option.text || textOf(option));
  const label = normalizeSelectionText(option.getAttribute?.("label") || "");
  if (!expected || (!text && !label)) return false;
  if (text === expected || label === expected) return true;
  if (expected.length < 3) return false;
  return text.includes(expected) || expected.includes(text) || label.includes(expected);
}

function normalizeSelectionText(value) {
  return normalizeComparableText(value)
    .replace(/[\u2010-\u2015\u2212]/g, "-")
    .replace(/\s*-\s*/g, "-");
}

function selectOptionByText(select, value) {
  if (!select || !value) return false;

  const option = Array.from(select.options || []).find((candidate) => {
    if (!candidate.value) return false;
    return optionMatchesText(candidate, value) || valuesMatch(candidate.value, value);
  });
  if (!option) return false;

  setAngularSelectValue(select, option);
  return true;
}

async function selectCustomDropdownOptionByText(root, value, config = {}) {
  if (!root || !value) return false;

  const openerRoot = customDropdownFieldRoot(root, config.labelPatterns) || root;
  let openers = Array.from(openerRoot.querySelectorAll(
    [
      ".ui-select-toggle",
      ".dropdown-toggle",
      ".custom-multi-select",
      "[ng-click*='toggleDropdown']",
      "button",
    ].join(",")
  )).filter((candidate) => visibleElement(candidate) && !candidate.disabled);
  if (!openers.length && openerRoot !== root) {
    openers = Array.from(root.querySelectorAll(
      [
        ".ui-select-toggle",
        ".dropdown-toggle",
        ".custom-multi-select",
        "[ng-click*='toggleDropdown']",
        "button",
      ].join(",")
    )).filter((candidate) => visibleElement(candidate) && !candidate.disabled);
  }

  for (const opener of openers) {
    if (!visibleDropdownOptions(root).length) {
      opener.click();
      await wait(150);
    }

    const option = visibleDropdownOptions(root).find((candidate) => optionMatchesText(candidate, value));
    if (option) {
      const clickable = option.querySelector("a, button, label, span") || option;
      clickable.click();
      await waitForNetworkIdle();
      await wait(250);
      return true;
    }
  }

  const options = visibleDropdownOptions(root);
  console.warn("Helper Toolkit: custom dropdown option not found.", {
    value,
    options: options.map((option) => textOf(option)).filter(Boolean).slice(0, 25),
  });
  return false;
}

function customDropdownFieldRoot(root, labelPatterns = []) {
  if (!root || !labelPatterns?.length) return null;

  const label = Array.from(root.querySelectorAll("label, span, strong")).find((candidate) => {
    const text = normalizeComparableText(textOf(candidate));
    return text && labelPatterns.some((pattern) => pattern.test(text));
  });
  if (!label) return null;

  return (
    label.closest(".form-group, [class*='col-'], .row, .ng-scope") ||
    label.parentElement ||
    null
  );
}

function visibleDropdownOptions(root) {
  const selector = [
    ".dropdown-menu li",
    ".dropdown-menu a",
    ".ui-select-choices-row",
    "[role='option']",
    "[ng-repeat*='floor']",
    "[ng-repeat*='option']",
  ].join(",");

  return Array.from(root.querySelectorAll(selector)).filter((candidate) => {
    if (!visibleElement(candidate)) return false;
    const text = textOf(candidate);
    if (!text) return false;
    if (/filter here|^filter$|check\s+all|uncheck\s+all|^select:?$/i.test(text)) return false;
    if (candidate.querySelector?.("input")) return false;
    return true;
  });
}

