async function fillFloorEditorFields(editor, item, floorValue, tableRow = null) {
  await selectFloorWorkTypes(editor, item, tableRow);

  const proposed =
    rowValueByHeader(tableRow, proposedWorkNotOnSoHeaderPatterns) ||
    cellValueByHeader(item.cellData, proposedWorkNotOnSoHeaderPatterns);
  const proposedCheckbox = editor.root.querySelector('input[type="checkbox"][ng-model="workOnFloorFormObj.ProposedWorkIsNotScheduleOfOccupany"]');
  if (proposedCheckbox && proposed) {
    const desired = booleanValue(proposed);
    if (proposedCheckbox.checked !== desired) proposedCheckbox.click();
    await waitForNetworkIdle();
  }

  const selectedFloor = editor.root.querySelector("#SelectedFloorFDSelCategoryWorklist, select[name='SelectedFloorFDSelCategoryWorklist']");
  const location = editor.root.querySelector("#FloorFDSelCategoryWorklist1, select[name='FloorFDSelCategoryWorklist1']");
  const description = editor.root.querySelector("#txtDOW, textarea[ng-model='workOnFloorFormObj.FloorDescription']");
  const locationText =
    rowValueByHeader(tableRow, [/location/i]) ||
    cellValueByHeader(item.cellData, [/location/i, /floor.*location/i]);
  const descriptionText =
    rowValueByHeader(tableRow, [/description/i, /use.*comment/i]) ||
    cellValueByHeader(item.cellData, [/description/i]) ||
    item.rowData?.FloorDescription ||
    "";

  if (selectedFloor && visibleElement(selectedFloor)) {
    if (!selectOptionByText(selectedFloor, floorValue)) {
      const selectedCustom = await selectCustomDropdownOptionByText(editor.root, floorValue, {
        labelPatterns: [/selected\s+floor/, /floor\/use/],
      });

