async function selectFloorWorkTypes(editor, item, tableRow = null) {
  const workTypeText =
    rowValueByHeader(tableRow, [/work\s*type/i]) ||
    cellValueByHeader(item.cellData, [/work\s*type/i]) ||
    item.rowData?.WorkTypeName ||
    "";
  const values = String(workTypeText || "")
    .split(/[,;/\n]+/)
    .map((value) => value.trim())
    .filter(Boolean);
  if (!values.length) return true;

  const multiselect = editor.root.querySelector('[selected-model="SelectedWorkTypeListForWF"], [name="SelectedWorkTypeListForWF"]');
  const parent = multiselect?.querySelector?.(".dropdown-multiselect, .multiselect-parent") || multiselect?.closest?.(".dropdown-multiselect, .multiselect-parent");
  if (!parent) return true;

  const button = parent.querySelector(".dropdown-toggle");
  const menu = parent.querySelector(".dropdown-menu");
  if (button && menu && getComputedStyle(menu).display === "none") {
    button.click();
    await wait(150);
  }

  values.forEach((value) => {
    const option = Array.from(parent.querySelectorAll('li[ng-repeat] a[ng-click*="setSelectedItem"], li[role="presentation"] a[ng-click*="setSelectedItem"]'))
      .find((candidate) => normalizeComparableText(textOf(candidate).replace(/^check\s*/i, "")) === normalizeComparableText(value));
    if (option && !isMultiselectOptionChecked(option)) option.click();
  });
  if (button && menu && getComputedStyle(menu).display !== "none") {
    button.click();
  }
  await wait(250);
  return true;
}

