function floorDisplaySummary(item) {
  const cellData = item.cellData && typeof item.cellData === "object" ? item.cellData : {};
  const bindings = tableColumnBindings(item);
  const parts = Object.entries(cellData)
    .filter(([header, value]) => {
      const normalized = normalizeComparableText(header);
      if (!String(value ?? "").trim()) return false;
      if (/^actions?$/.test(normalized)) return false;
      if (/selected.*floor|floor.*use|^floor$|location/.test(normalized)) return false;
      return true;
    })
    .map(([header, value]) => bindings[header] ? `[${bindings[header]}] ${header}` : cleanDisplayCellValue(value))
    .filter(Boolean);

  parts.push(floorValueLabel(item));
  return parts.join(" / ");
}

function floorComparableFields(item) {
  const cellData = item.cellData && typeof item.cellData === "object" ? item.cellData : {};
  return Object.entries(cellData)
    .filter(([header, value]) => {
      const normalized = normalizeComparableText(header);
      if (!String(value ?? "").trim()) return false;
      if (/^actions?$/.test(normalized)) return false;
      if (/selected.*floor|floor.*use|^floor$|location/.test(normalized)) return false;
      return true;
    })
    .map(([header, value]) => [normalizeComparableText(header), normalizeComparableText(cleanDisplayCellValue(value))])
    .sort(([left], [right]) => left.localeCompare(right));
}

function floorMergeSignature(item) {
  return JSON.stringify({
    type: item.type,
    tableKind: "floor",
    query: item.query || "",
    gridName: item.gridName || "",
    tab: tabLabel(item.tab),
    section: sectionLabel(item.section),
    fields: floorComparableFields(item),
  });
}

function floorMergeParts(item) {
  return {
    query: item.query || "",
    gridName: item.gridName || "",
    tab: tabLabel(item.tab),
    section: sectionLabel(item.section),
    fields: floorComparableFields(item),
  };
}

function logFloorMergeMiss(items, item) {
  if (!isFloorStoredItem(item) || item.dynamicColumn) return;

  const existing = items.find((stored) => isFloorStoredItem(stored) && !stored.dynamicColumn);
  if (!existing) return;

  const currentParts = floorMergeParts(item);
  const existingParts = floorMergeParts(existing);
  const differences = Object.keys(currentParts).reduce((diff, key) => {
    if (JSON.stringify(currentParts[key]) !== JSON.stringify(existingParts[key])) {
      diff[key] = { existing: existingParts[key], current: currentParts[key] };
    }
    return diff;
  }, {});

  if (Object.keys(differences).length) {
    console.log("Helper Toolkit floor rows did not merge because these fields differ:", differences, {
      existing,
      current: item,
    });
  }
}

function mergeFloorValueText(left, right) {
  const seen = new Set();
  return [left, right]
    .flatMap((value) => String(value ?? "").split(/\r?\n/))
    .map((value) => value.trim())
    .filter((value) => {
      const key = normalizeComparableText(value);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .join("\n");
}

function mergeableStoredFloorIndex(items, item) {
  if (!isFloorStoredItem(item) || item.dynamicColumn) return -1;
  const signature = floorMergeSignature(item);
  return items.findIndex((stored) =>
    isFloorStoredItem(stored) &&
    !stored.dynamicColumn &&
    floorMergeSignature(stored) === signature
  );
}

function isFloorStoredItem(item) {
  return item?.type === "trInspectionRow" && (
    item.tableKind === "floor" ||
    tableRowConfigForGrid(item.gridName)?.kind === "floor"
  );
}

function floorGridMatches(gridName, gridElement) {
  if (/floor/i.test(String(gridName || ""))) return true;
  if (!gridElement) return false;

  const headers = Array.from(gridElement.querySelectorAll(".ui-grid-header-cell")).map((cell) =>
    normalizeComparableText(textOf(cell))
  );
  const headerText = headers.join(" ");
  return (
    /work/.test(headerText) &&
    /floor|location/.test(headerText) &&
    (/description/.test(headerText) || /use/.test(headerText))
  );
}

function floorValueFromTableRow(row) {
  return rowValueByHeader(row, [/location\s*information/i, /selected.*floor/i, /floor.*use/i, /^floor$/i, /^location$/i]);
}

function floorValueExistsInGrid(item, floorValue) {
  const grid = getElement(item);
  if (!grid || !floorValue) return false;

