804	        if (escaped) {
805	          escaped = false;
806	          continue;
807	        }
808	        if (char === "\\") {
809	          escaped = true;
810	          continue;
811	        }
812	        if (char === openChar) depth += 1;
813	        if (char === closeChar) depth -= 1;
814	        if (depth === 0) return { value: text.slice(start + 1, index), end: index + 1 };
815	      }
816	      return null;
817	    }
