1838	    function ellipsizePdfText(doc, text, maxWidth) {
1839	      const value = normalizeText(text).replace(/\s+/g, " ").trim();
1840	      if (!value || doc.getTextWidth(value) <= maxWidth) return value;
1841	
1842	      let low = 0;
1843	      let high = value.length;
1844	      while (low < high) {
1845	        const mid = Math.ceil((low + high) / 2);
1846	        if (doc.getTextWidth(`${value.slice(0, mid)}...`) <= maxWidth) low = mid;
1847	        else high = mid - 1;
1848	      }
1849	      return `${value.slice(0, low)}...`;
1850	    }
