1852	    function getPdfColumnWidths(doc, columns, rows, availableWidth) {
1853	      const widths = columns.map(column => {
1854	        if (column.key === "preview") return Math.min(160, Math.max(80, state.thumbnailSettings.width * 0.6));
1855	        const textWidth = Math.max(
1856	          doc.getTextWidth(column.label),
1857	          ...rows.map(row => doc.getTextWidth(normalizeText(column.value(row)).replace(/\s+/g, " ").trim()))
1858	        );
1859	        return Math.min(140, Math.max(56, textWidth + 16));
1860	      });
1861	
1862	      const total = widths.reduce((sum, width) => sum + width, 0);
1863	      if (total <= availableWidth) return widths;
1864	
1865	      const previewWidth = columns.reduce((sum, column, index) => sum + (column.key === "preview" ? widths[index] : 0), 0);
1866	      const textIndexes = columns.map((column, index) => column.key === "preview" ? -1 : index).filter(index => index >= 0);
1867	      const textTotal = textIndexes.reduce((sum, index) => sum + widths[index], 0);
1868	      const textAvailable = Math.max(40 * textIndexes.length, availableWidth - previewWidth);
1869	      const scale = textAvailable / textTotal;
1870	      textIndexes.forEach(index => {
1871	        widths[index] = Math.max(40, widths[index] * scale);
1872	      });
1873	      return widths;
1874	    }
