1930	        const previewWidth = previewColumnIndex >= 0 ? columnWidths[previewColumnIndex] : 0;
1931	        const previewBoxWidth = row.thumbnail && previewWidth ? Math.max(1, previewWidth - cellPadding * 2) : 0;
1932	        const previewBoxHeight = row.thumbnail
1933	          ? Math.max(1, previewBoxWidth * (row.thumbnailHeight || 1) / (row.thumbnailWidth || 1))
1934	          : 0;
1935	        const rowHeight = Math.max(22, previewBoxHeight + cellPadding * 2);
