      thumbnailHeightInput.value = height;
      thumbnailMarginInput.value = marginPercent;
      return { width, height, marginPercent };
    }

    function applyThumbnailSettingsToInputs(settings) {
      thumbnailWidthInput.value = settings.width;
      thumbnailHeightInput.value = settings.height;
      thumbnailMarginInput.value = settings.marginPercent;
    }

    function loadThumbnailSettings() {
      const saved = localStorage.getItem(storageKeys.thumbnailSettings);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          state.thumbnailSettings = {
            width: Math.max(32, Math.min(400, Number(parsed.width) || state.thumbnailSettings.width)),
            height: Math.max(32, Math.min(300, Number(parsed.height) || state.thumbnailSettings.height)),
            marginPercent: Math.max(0, Math.min(300, Number(parsed.marginPercent) || 0)),
          };
        } catch (error) {
          console.warn("Could not load thumbnail settings:", error);
        }
      }
      applyThumbnailSettingsToInputs(state.thumbnailSettings);
    }

    function saveThumbnailSettings() {
      localStorage.setItem(storageKeys.thumbnailSettings, JSON.stringify(state.thumbnailSettings));
    }

    async function generateMarkupThumbnails(pdf, markups) {
      const settings = state.thumbnailSettings;
      const targetAspect = settings.width / settings.height;
      const markupsByPage = new Map();
      markups.forEach(markup => {
        if (!markupsByPage.has(markup.page)) markupsByPage.set(markup.page, []);
        markupsByPage.get(markup.page).push(markup);
      });

      for (const [pageNumber, pageMarkups] of markupsByPage.entries()) {
        const page = await pdf.getPage(pageNumber);
        const viewport = page.getViewport({ scale: 1.25 });
        const pageCanvas = document.createElement("canvas");
        pageCanvas.width = Math.ceil(viewport.width);
        pageCanvas.height = Math.ceil(viewport.height);
        await page.render({ canvasContext: pageCanvas.getContext("2d"), viewport }).promise;

        pageMarkups.forEach(markup => {
          const bounds = getViewportBounds(markup, viewport);
          if (!bounds) return;

          const crop = clampCrop(bounds, pageCanvas, settings.marginPercent, targetAspect);
          const thumbWidth = settings.width;
          const thumbHeight = settings.height;
          const thumbnail = document.createElement("canvas");
          thumbnail.width = thumbWidth;
          thumbnail.height = thumbHeight;
          const context = thumbnail.getContext("2d");
          context.fillStyle = "#ffffff";
          context.fillRect(0, 0, thumbWidth, thumbHeight);

          const scale = thumbWidth / crop.width;
          context.drawImage(pageCanvas, crop.x, crop.y, crop.width, crop.height, 0, 0, thumbWidth, thumbHeight);
          drawThumbnailOverlay(context, markup, bounds, crop, scale, 0, 0);
          markup.thumbnail = thumbnail.toDataURL("image/png");
          markup.thumbnailWidth = thumbWidth;
          markup.thumbnailHeight = thumbHeight;
        });
      }
    }

    async function regenerateThumbnailsFromInputs() {
      if (!state.pdf || !state.markups.length) return;
      state.thumbnailSettings = getThumbnailSettingsFromInputs();
      saveThumbnailSettings();
      applyThumbnailSettingsButton.disabled = true;
      setStatus("Regenerating markup thumbnails...");
      await generateMarkupThumbnails(state.pdf, state.markups);
      renderHeaders();
      renderRows();
      setStatus(`Updated thumbnails to ${state.thumbnailSettings.width} x ${state.thumbnailSettings.height} with ${state.thumbnailSettings.marginPercent}% margin.`, "ok");
      applyThumbnailSettingsButton.disabled = false;
    }

    function drawOverlay() {
      overlay.innerHTML = "";
      if (!state.viewport) return;
      const visible = state.filteredMarkups.filter(markup => markup.page === state.currentPage);
      visible.forEach(markup => {
        const isActive = markup.id === state.selectedId;
        const color = colorToCss(markup.color, isActive ? "27, 111, 216" : "217, 45, 32");
        let shape;
        if (markup.vertices?.length >= 4) {
          shape = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
          shape.setAttribute("points", verticesToPoints(markup.vertices).join(" "));
        } else if (markup.rect?.length === 4) {
          const rect = rectToViewport(markup.rect);
          shape = document.createElementNS("http://www.w3.org/2000/svg", "rect");
          shape.setAttribute("x", rect.x);
          shape.setAttribute("y", rect.y);
          shape.setAttribute("width", rect.width);
          shape.setAttribute("height", rect.height);
        }
        if (!shape) return;
        shape.setAttribute("fill", isActive ? "var(--active-fill)" : "var(--mark-fill)");
        shape.setAttribute("stroke", isActive ? "var(--accent)" : color);
        shape.setAttribute("stroke-width", isActive ? 3 : 1.8);
        shape.setAttribute("vector-effect", "non-scaling-stroke");
        overlay.append(shape);
      });
    }

    function renderRaw(markup) {
      if (!markup) {
        rawBody.innerHTML = '<pre class="raw-pre">Select a markup to inspect PDF.js annotation data, raw PDF object fields, vertices, measurement data, and Bluebeam column values when present.</pre>';
        copyRawButton.disabled = true;
        return;
      }
      copyRawButton.disabled = false;
      const keyRows = [
        ["Source", markup.source],
        ["Page", markup.page],
        ["Subtype", markup.subtype],
        ["Subject", markup.subject],
        ["Label", markup.label],
        ["Contents", markup.contents],
        ["Value", getMarkupValue(markup)],
        ["Author", markup.author],
        ["Created", markup.creationDate],
        ["Modified", markup.modifiedDate],
        ["Rect", markup.rect?.join(", ")],
        ["Vertices", markup.vertices?.join(", ")],
        ["Color", markup.color?.join(", ")],
        ["Object", markup.raw?.objectHeader],
        ["Bluebeam Columns", markup.raw?.bsiColumnData?.join(", ")],
        ["Raw Keys", markup.raw?.rawKeys?.join(", ")],
      ];
      const summary = keyRows.map(([key, value]) => `
        <div class="raw-key">${escapeHtml(key)}</div>
        <div class="raw-value">${escapeHtml(normalizeText(value) || "-")}</div>
      `).join("");
      rawBody.innerHTML = `
        <div class="raw-grid">${summary}</div>
        <pre class="raw-pre">${escapeHtml(JSON.stringify({
          normalized: {
            id: markup.id,
            page: markup.page,
            subtype: markup.subtype,
            subject: markup.subject,
            label: markup.label,
            contents: markup.contents,
            value: getMarkupValue(markup),
            author: markup.author,
            creationDate: markup.creationDate,
            modifiedDate: markup.modifiedDate,
            rect: markup.rect,
            vertices: markup.vertices,
            color: markup.color,
            source: markup.source,
          },
          bluebeamRaw: markup.raw,
          pdfJsAnnotation: markup.annotation,
        }, null, 2))}</pre>
      `;
    }

    function selectMarkup(id) {
      state.selectedId = id;
      const markup = state.markups.find(candidate => candidate.id === id);
      if (markup && markup.page !== state.currentPage) {
        renderPage(markup.page);
      } else {
        drawOverlay();
      }
      renderRows();
      renderRaw(markup);
      updateMetrics();
    }

    async function loadPdfFromBytes(bytes, fileName) {
      setStatus("Loading PDF and extracting markups...");
      state.bytes = bytes;
      state.fileName = fileName;
      state.hiddenColumns = new Set();
      state.thumbnailSettings = getThumbnailSettingsFromInputs();
      applyThumbnailSettingsButton.disabled = true;
      copySheetsButton.disabled = true;
      downloadTablePdfButton.disabled = true;
      state.bsiColumnDefinitions = parseBsiAnnotColumns(bytes);
      state.rawObjects = extractRawAnnotationObjects(bytes);
      const loadingTask = pdfjsLib.getDocument({ data: bytes.slice().buffer });
      state.pdf = await loadingTask.promise;
      state.markups = await extractPdfJsMarkups(state.pdf, state.rawObjects);
      setStatus("Generating markup thumbnails...");
      await generateMarkupThumbnails(state.pdf, state.markups);
      state.rawColumns = getExpandedRawColumns(state.markups);
      setDefaultVisibleColumns();
      state.selectedId = state.markups[0]?.id ?? null;
      state.currentPage = state.markups[0]?.page ?? 1;
      state.filteredMarkups = state.markups;

      visualizerTitle.textContent = fileName;
      pageCountText.textContent = `of ${state.pdf.numPages}`;
      pageNumberInput.disabled = false;
      previousPageButton.disabled = false;
      nextPageButton.disabled = false;
      downloadJsonButton.disabled = false;
      copySheetsButton.disabled = false;
      downloadTablePdfButton.disabled = false;
      applyThumbnailSettingsButton.disabled = false;
      renderHeaders();
      updatePageFilter();
      applyFilters();
      updateMetrics();
      await renderPage(state.currentPage);
      renderRaw(state.markups.find(markup => markup.id === state.selectedId));
      setStatus(`Loaded ${state.markups.length} markup${state.markups.length === 1 ? "" : "s"} from ${fileName}.`, "ok");
    }

    async function loadDefaultPdf() {
      try {
        const response = await fetch(defaultPdfUrl);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const bytes = new Uint8Array(await response.arrayBuffer());
        await loadPdfFromBytes(bytes, "Floor Area Markup_Wagner College Survey_new.pdf");
      } catch (error) {
        setStatus(`Could not load the sample PDF. Open this app through a web server, then try again. ${error.message}`, "error");
      }
    }

    async function loadChosenFile(file) {
      if (!file) return;
      const bytes = new Uint8Array(await file.arrayBuffer());
      await loadPdfFromBytes(bytes, file.name);
    }

    function downloadJson() {
      const data = {
        fileName: state.fileName,
        extractedAt: new Date().toISOString(),
        pageCount: state.pdf?.numPages ?? 0,
        bsiColumnDefinitions: state.bsiColumnDefinitions,
        markups: state.markups.map(markup => ({
          id: markup.id,
          page: markup.page,
          subtype: markup.subtype,
          subject: markup.subject,
          label: markup.label,
          contents: markup.contents,
          value: getMarkupValue(markup),
          author: markup.author,
          creationDate: markup.creationDate,
          modifiedDate: markup.modifiedDate,
          rect: markup.rect,
          vertices: markup.vertices,
          color: markup.color,
          source: markup.source,
          raw: markup.raw,
        })),
      };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `${state.fileName.replace(/\.pdf$/i, "") || "markups"}-markup-data.json`;
      document.body.append(link);
      link.click();
      link.remove();
      window.setTimeout(() => URL.revokeObjectURL(url), 0);
    }

    function pdfSafeName(name) {
      return (name || "markup-table").replace(/\.pdf$/i, "").replace(/[^a-z0-9._-]+/gi, "-").replace(/^-+|-+$/g, "") || "markup-table";
    }

    function escapeHtmlAttribute(value) {
      return String(value ?? "").replace(/[&<>"']/g, char => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "\"": "&quot;",
        "'": "&#039;",
      }[char]));
    }

    function escapeTsvValue(value) {
      const text = normalizeText(value).replace(/\r?\n/g, " ");
      return /[\t"]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
    }

    function getSheetsColumnWidth(column) {
      if (column.key === "preview") return state.thumbnailSettings.width;
      return Math.min(220, Math.max(70, Math.round((column.label.length + 4) * 8)));
    }

    function buildSheetsHtml(columns, rows) {
      const colgroup = columns.map(column => `<col width="${getSheetsColumnWidth(column)}">`).join("");
      const rowHeight = Math.max(21, state.thumbnailSettings.height + 6);
      const tdBase = "border: 1px solid rgb(204, 204, 204); overflow: hidden; padding: 2px 3px; vertical-align: middle;";
      const header = `<tr style="height: 21px;">${columns.map(column => (
        `<td style="${tdBase} font-weight: bold;">${escapeHtml(column.label)}</td>`
      )).join("")}</tr>`;
      const body = rows.map(row => `<tr style="height: ${rowHeight}px;">${columns.map(column => {
        if (column.key === "preview") {
          return `<td style="${tdBase} width: ${state.thumbnailSettings.width}px; height: ${state.thumbnailSettings.height}px;"><img src="${escapeHtmlAttribute(row.thumbnail || "")}" style="width: inherit; height: inherit; object-fit: scale-down; object-position: left center; pointer-events: none;"></td>`;
        }
        return `<td style="${tdBase} white-space: normal; overflow-wrap: break-word;">${escapeHtml(column.value(row))}</td>`;
      }).join("")}</tr>`).join("");

      return `<google-sheets-html-origin style="color: rgb(0, 0, 0); font-size: medium; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"><table xmlns="http://www.w3.org/1999/xhtml" cellspacing="0" cellpadding="0" dir="ltr" border="1" data-sheets-root="1" data-sheets-baot="1" style="table-layout: fixed; font-size: 10pt; font-family: Arial; width: 0px; border-collapse: collapse; border-width: medium; border-style: none; border-color: currentcolor; border-image: initial;"><colgroup>${colgroup}</colgroup><tbody>${header}${body}</tbody></table></google-sheets-html-origin>`;
    }

    function buildSheetsPlainText(columns, rows) {
      const header = columns.map(column => escapeTsvValue(column.label)).join("\t");
      const body = rows.map(row => columns.map(column => (
        column.key === "preview" ? "" : escapeTsvValue(column.value(row))
      )).join("\t")).join("\n");
      return `${header}\n${body}`;
    }

    async function copyTableForGoogleSheets() {
      const rows = state.filteredMarkups.length ? state.filteredMarkups : state.markups;
      const columns = getVisibleTableColumns();
      if (!rows.length || !columns.length) {
        setStatus("There is no table data to copy.", "warn");
        return;
      }

      const html = buildSheetsHtml(columns, rows);
      const plain = buildSheetsPlainText(columns, rows);
      try {
        if (window.ClipboardItem && navigator.clipboard?.write) {
          await navigator.clipboard.write([
            new ClipboardItem({
              "text/html": new Blob([html], { type: "text/html" }),
              "text/plain": new Blob([plain], { type: "text/plain" }),
            }),
          ]);
        } else {
          await navigator.clipboard.writeText(plain);
        }
        setStatus(`Copied ${rows.length} table row${rows.length === 1 ? "" : "s"} for Google Sheets.`, "ok");
      } catch (error) {
        console.error(error);
        setStatus("Could not copy the table to the clipboard.", "error");
      }
    }

    function ellipsizePdfText(doc, text, maxWidth) {
      const value = normalizeText(text).replace(/\s+/g, " ").trim();
      if (!value || doc.getTextWidth(value) <= maxWidth) return value;

      let low = 0;
      let high = value.length;
      while (low < high) {
        const mid = Math.ceil((low + high) / 2);
        if (doc.getTextWidth(`${value.slice(0, mid)}...`) <= maxWidth) low = mid;
        else high = mid - 1;
      }
      return `${value.slice(0, low)}...`;
    }

    function getPdfColumnWidths(doc, columns, rows, availableWidth) {
      const widths = columns.map(column => {
        if (column.key === "preview") return Math.min(160, Math.max(80, state.thumbnailSettings.width * 0.6));
        const textWidth = Math.max(
          doc.getTextWidth(column.label),
          ...rows.map(row => doc.getTextWidth(normalizeText(column.value(row)).replace(/\s+/g, " ").trim()))
        );
        return Math.min(140, Math.max(56, textWidth + 16));
      });

      const total = widths.reduce((sum, width) => sum + width, 0);
      if (total <= availableWidth) return widths;

      const previewWidth = columns.reduce((sum, column, index) => sum + (column.key === "preview" ? widths[index] : 0), 0);
      const textIndexes = columns.map((column, index) => column.key === "preview" ? -1 : index).filter(index => index >= 0);
      const textTotal = textIndexes.reduce((sum, index) => sum + widths[index], 0);
      const textAvailable = Math.max(40 * textIndexes.length, availableWidth - previewWidth);
      const scale = textAvailable / textTotal;
      textIndexes.forEach(index => {
        widths[index] = Math.max(40, widths[index] * scale);
      });
      return widths;
    }

    function downloadTablePdf() {
      const jsPdfConstructor = window.jspdf?.jsPDF;
      if (!jsPdfConstructor) {
        setStatus("PDF export library is still loading. Try again in a moment.", "warn");
        return;
      }

      const rows = state.filteredMarkups.length ? state.filteredMarkups : state.markups;
      const columns = getVisibleTableColumns();
      if (!rows.length || !columns.length) {
        setStatus("There is no table data to export.", "warn");
        return;
      }

      const doc = new jsPdfConstructor({ orientation: "landscape", unit: "pt", format: "letter" });
      const margin = 32;
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const availableWidth = pageWidth - margin * 2;
      const columnWidths = getPdfColumnWidths(doc, columns, rows, availableWidth);
      const headerHeight = 24;
      const textLineHeight = 12;
      const cellPadding = 5;
      let y = margin;

      function drawHeader() {
        let x = margin;
        doc.setFillColor(250, 251, 252);
        doc.setDrawColor(215, 220, 226);
        columns.forEach((column, index) => {
          const width = columnWidths[index];
          doc.rect(x, y, width, headerHeight, "FD");
          x += width;
        });

        x = margin;
        doc.setTextColor(102, 112, 133);
        doc.setFont("helvetica", "bold");
        doc.setFontSize(8);
        columns.forEach((column, index) => {
          const width = columnWidths[index];
          doc.text(ellipsizePdfText(doc, column.label, width - cellPadding * 2), x + cellPadding, y + 15);
          x += width;
        });
        y += headerHeight;
      }

      drawHeader();
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      doc.setTextColor(23, 32, 42);

      rows.forEach(row => {
        const previewColumnIndex = columns.findIndex(column => column.key === "preview");
        const previewWidth = previewColumnIndex >= 0 ? columnWidths[previewColumnIndex] : 0;
        const previewBoxWidth = row.thumbnail && previewWidth ? Math.max(1, previewWidth - cellPadding * 2) : 0;
        const previewBoxHeight = row.thumbnail
          ? Math.max(1, previewBoxWidth * (row.thumbnailHeight || 1) / (row.thumbnailWidth || 1))
          : 0;
        const rowHeight = Math.max(22, previewBoxHeight + cellPadding * 2);

        if (y + rowHeight > pageHeight - margin) {
          doc.addPage();
          y = margin;
          drawHeader();
          doc.setFont("helvetica", "normal");
          doc.setFontSize(8);
          doc.setTextColor(23, 32, 42);
        }

        let x = margin;
        doc.setDrawColor(215, 220, 226);
        columns.forEach((column, index) => {
          const width = columnWidths[index];
          doc.rect(x, y, width, rowHeight);
          if (column.key === "preview" && row.thumbnail) {
            const imageMaxWidth = Math.max(1, width - cellPadding * 2);
            const imageMaxHeight = Math.max(1, rowHeight - cellPadding * 2);
            const imageScale = Math.min(
              imageMaxWidth / (row.thumbnailWidth || 1),
              imageMaxHeight / (row.thumbnailHeight || 1)
            );
            const imageWidth = (row.thumbnailWidth || 1) * imageScale;
            const imageHeight = (row.thumbnailHeight || 1) * imageScale;
            doc.addImage(row.thumbnail, "PNG", x + (width - imageWidth) / 2, y + (rowHeight - imageHeight) / 2, imageWidth, imageHeight);
          } else {
            const value = ellipsizePdfText(doc, column.value(row), width - cellPadding * 2);
            doc.text(value, x + cellPadding, y + cellPadding + textLineHeight);
          }
          x += width;
        });
        y += rowHeight;
      });

      doc.save(`${pdfSafeName(state.fileName)}-markup-table.pdf`);
      setStatus(`Downloaded ${rows.length} table row${rows.length === 1 ? "" : "s"} as PDF.`, "ok");
    }

    async function copySelectedRaw() {
      const markup = state.markups.find(candidate => candidate.id === state.selectedId);
      if (!markup) return;
      await navigator.clipboard.writeText(JSON.stringify({
        normalized: {
          id: markup.id,
          page: markup.page,
          subtype: markup.subtype,
          subject: markup.subject,
          label: markup.label,
          contents: markup.contents,
          value: getMarkupValue(markup),
          author: markup.author,
          creationDate: markup.creationDate,
          modifiedDate: markup.modifiedDate,
          rect: markup.rect,
          vertices: markup.vertices,
          color: markup.color,
          source: markup.source,
        },
        bluebeamRaw: markup.raw,
        pdfJsAnnotation: markup.annotation,
      }, null, 2));
      setStatus("Copied selected raw markup data.", "ok");
    }

    loadDefaultButton.addEventListener("click", loadDefaultPdf);
    fileInput.addEventListener("change", () => loadChosenFile(fileInput.files[0]));
    filterInput.addEventListener("input", applyFilters);
    pageFilter.addEventListener("change", applyFilters);
    downloadJsonButton.addEventListener("click", downloadJson);
    copySheetsButton.addEventListener("click", copyTableForGoogleSheets);
    downloadTablePdfButton.addEventListener("click", downloadTablePdf);
    copyRawButton.addEventListener("click", copySelectedRaw);
    applyThumbnailSettingsButton.addEventListener("click", regenerateThumbnailsFromInputs);
    columnMenuButton.addEventListener("click", () => {
      setColumnMenuOpen(columnMenu.hidden);
    });
    document.addEventListener("click", event => {
      if (columnMenu.hidden) return;
      if (columnMenu.contains(event.target) || columnMenuButton.contains(event.target)) return;
      setColumnMenuOpen(false);
    });
    document.addEventListener("keydown", event => {
      if (event.key === "Escape") setColumnMenuOpen(false);
    });
    previousPageButton.addEventListener("click", () => renderPage(state.currentPage - 1));
    nextPageButton.addEventListener("click", () => renderPage(state.currentPage + 1));
    pageNumberInput.addEventListener("change", () => renderPage(pageNumberInput.value));
    window.addEventListener("resize", () => {
      if (state.pdf) renderPage(state.currentPage);
    });

    loadThumbnailSettings();
    loadDefaultPdf();
  </script>
</body>
</html>

