function renderPresetOptions(selectedName = presetSelect.value) {
  const presets = readPresets();
  const names = Object.keys(presets).sort((a, b) => a.localeCompare(b));

  presetSelect.innerHTML = "";
  const emptyOption = document.createElement("option");
  emptyOption.value = "";
  emptyOption.textContent = names.length ? "Select preset" : "No presets saved";
  presetSelect.append(emptyOption);

  for (const name of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    presetSelect.append(option);
  }

  const resolvedName = names.includes(selectedName) ? selectedName : "";
  presetSelect.value = resolvedName;
  loadPresetButton.disabled = !resolvedName;
  deletePresetButton.disabled = !resolvedName;
  saveActivePresetName(resolvedName);
}

function getCurrentPresetData() {
  return {
    pattern: patternInput.value,
    searchMode: searchModeSelect.value,
    recursive: recursiveInput.checked,
    recurseDepth: recurseDepthInput.value,
    caseInsensitive: caseInsensitiveInput.checked,
    extractText: extractTextInput.checked,
    extractPage: extractPageInput.value,
    dirList: dirListTextarea.value,
    columns: dynamicColumns.map(serializeColumn),
  };
}

function applyPresetData(preset) {
  patternInput.value = String(preset.pattern || "");
  const mode = String(preset.searchMode || "filename");
  searchModeSelect.value = [...searchModeSelect.options].some(option => option.value === mode) ? mode : "filename";
  recursiveInput.checked = Boolean(preset.recursive);
  recurseDepthInput.value = String(preset.recurseDepth || "");
  caseInsensitiveInput.checked = preset.caseInsensitive !== false;
  extractTextInput.checked = Boolean(preset.extractText);
  extractPageInput.value = String(preset.extractPage || "");
  dirListTextarea.value = String(preset.dirList || "");
  dynamicColumns = Array.isArray(preset.columns)
    ? preset.columns.map(normalizeColumn)
    : [];

  updateFolderListCount();
  saveInputs();
  renderHeaders();
  renderColumnTags();
  renderRows();
}

function setStatus(message, type = "") {
  statusBox.textContent = message;
  statusBox.className = `status ${type}`.trim();
}

function formatBytes(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB", "TB"];
  let value = bytes / 1024;
  let unit = units.shift();
  while (value >= 1024 && units.length) {
    value /= 1024;
    unit = units.shift();
  }
  return `${value.toFixed(value >= 10 ? 1 : 2)} ${unit}`;
}

