function readPresets() {
  const saved = localStorage.getItem(storageKeys.presets);
  if (!saved) return {};
  try {
    const presets = JSON.parse(saved);
    return presets && typeof presets === "object" && !Array.isArray(presets) ? presets : {};
  } catch (error) {
    console.warn("Could not load Markup Viz presets:", error);
    return {};
  }
}

function writePresets(presets) {
  localStorage.setItem(storageKeys.presets, JSON.stringify(presets));
}

function saveActivePresetName(name) {
  if (name) {
    localStorage.setItem(storageKeys.activePreset, name);
  } else {
    localStorage.removeItem(storageKeys.activePreset);
  }
}

function getCurrentPresetData() {
  const columns = getTableColumns();
  return {
    visibleColumns: columns
      .filter(column => !state.hiddenColumns.has(column.key))
      .map(column => ({ key: column.key, label: column.label })),
    allColumnKeys: columns.map(column => column.key),
    thumbnailSettings: { ...state.thumbnailSettings },
  };
}

// Applies a preset's column visibility against the columns the currently loaded PDF
// actually has. Columns the preset wanted on but that don't exist here are reported
// back (surfaced as a status message); columns that exist now but weren't known when
// the preset was saved are tracked so the column menu can flag them.
function applyColumnPreset(preset) {
  const currentColumns = getTableColumns();
  const currentKeys = new Set(currentColumns.map(column => column.key));
  const requested = (Array.isArray(preset.visibleColumns) ? preset.visibleColumns : [])
    .map(entry => (typeof entry === "string" ? { key: entry, label: entry } : entry))
    .filter(entry => entry && entry.key);
  const requestedKeys = new Set(requested.map(entry => entry.key));
  const savedAllKeys = new Set(
    Array.isArray(preset.allColumnKeys) && preset.allColumnKeys.length
      ? preset.allColumnKeys
      : requested.map(entry => entry.key)
  );

  const unavailable = requested.filter(entry => !currentKeys.has(entry.key));
  const newSinceSave = currentColumns.filter(column => !savedAllKeys.has(column.key));

  state.hiddenColumns = new Set(
    currentColumns.filter(column => !requestedKeys.has(column.key)).map(column => column.key)
  );
  state.unknownPresetColumns = new Set(newSinceSave.map(column => column.key));

  if (preset.thumbnailSettings) {
    state.thumbnailSettings = {
      width: Math.max(32, Math.min(400, Number(preset.thumbnailSettings.width) || state.thumbnailSettings.width)),
      height: Math.max(32, Math.min(300, Number(preset.thumbnailSettings.height) || state.thumbnailSettings.height)),
      marginPercent: Math.max(0, Math.min(300, Number(preset.thumbnailSettings.marginPercent) ?? state.thumbnailSettings.marginPercent)),
    };
    applyThumbnailSettingsToInputs(state.thumbnailSettings);
    saveThumbnailSettings();
  }

  return { unavailable: unavailable.map(entry => entry.label || entry.key) };
}

function renderPresetOptions(selectedName = presetSelect.value) {
  const presets = readPresets();
  const names = Object.keys(presets).sort((a, b) => a.localeCompare(b));

  presetSelect.innerHTML = "";
  const emptyOption = document.createElement("option");
  emptyOption.value = "";
  emptyOption.textContent = names.length ? "Select preset" : "No presets saved";
  presetSelect.append(emptyOption);

  for (const name of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    presetSelect.append(option);
  }

  const resolvedName = names.includes(selectedName) ? selectedName : "";
  presetSelect.value = resolvedName;
  loadPresetButton.disabled = !resolvedName;
  deletePresetButton.disabled = !resolvedName;
  saveActivePresetName(resolvedName);
}

function applyNamedPreset(name) {
  const preset = readPresets()[name];
  if (!preset) return;

  const { unavailable } = applyColumnPreset(preset);
  renderHeaders();
  renderRows();
  if (state.pdf && state.markups.length) regenerateThumbnailsFromInputs();

  presetNameInput.value = name;
  renderPresetOptions(name);
  if (unavailable.length) {
    setStatus(`Loaded preset "${name}". Not available in this PDF: ${unavailable.join(", ")}.`, "warn");
  } else {
    setStatus(`Loaded preset: ${name}`, "ok");
  }
}

