const puppeteer = require("puppeteer-core");

(async () => {
  const browser = await puppeteer.launch({
    executablePath: "/usr/bin/google-chrome",
    headless: "new",
    args: ["--no-sandbox", "--disable-dev-shm-usage"],
  });
  const page = await browser.newPage();
  await page.setDefaultTimeout(20000);
  const errors = [];
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  page.on("console", (msg) => {
    if (msg.type() === "error") errors.push("console.error: " + msg.text());
  });
  page.on("dialog", async (dialog) => {
    console.log("Clipboard permission dialog:", dialog.message());
    await dialog.accept();
  });

  const context = browser.defaultBrowserContext();
  await context.overridePermissions("http://127.0.0.1:8935", ["clipboard-read", "clipboard-write"]);

  await page.goto("http://127.0.0.1:8935/index.html", { waitUntil: "networkidle0" });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: "networkidle0" });

  await page.waitForFunction(() => window.__markupVizState && window.__markupVizState.markups.length > 0, { timeout: 20000 });
  console.log("PDF loaded, markup count:", await page.evaluate(() => window.__markupVizState.markups.length));

  // --- Save a preset with current default column visibility + thumbnail settings ---
  await page.click("#presetName");
  await page.type("#presetName", "My Preset");
  await page.click("#savePreset");
  await new Promise((r) => setTimeout(r, 200));
  let status = await page.$eval("#status", (el) => el.textContent);
  console.log("After save:", status);

  // --- Toggle a column off, then reload the same preset and confirm it restores ---
  await page.click("#columnMenuButton");
  await new Promise((r) => setTimeout(r, 150));
  const beforeHidden = await page.evaluate(() => window.__markupVizState.hiddenColumns.size);
  await page.evaluate(() => {
    const rows = [...document.querySelectorAll(".column-menu-row.is-child")];
    const row = rows.find((r) => r.textContent.includes("Author"));
    row.querySelector("input").click();
  });
  await new Promise((r) => setTimeout(r, 150));
  const afterToggle = await page.evaluate(() => window.__markupVizState.hiddenColumns.size);
  console.log("hiddenColumns before toggle:", beforeHidden, "after toggling Author off:", afterToggle);

  await page.select("#presetSelect", "My Preset");
  await new Promise((r) => setTimeout(r, 300));
  const afterLoad = await page.evaluate(() => window.__markupVizState.hiddenColumns.size);
  status = await page.$eval("#status", (el) => el.textContent);
  console.log("hiddenColumns after reloading preset:", afterLoad, "status:", status);

  // --- Simulate a preset saved before a new column existed: manually inject a stale preset ---
  await page.evaluate(() => {
    const presets = JSON.parse(localStorage.getItem("markupViz.presets"));
    const preset = presets["My Preset"];
    // Pretend one currently-known column key didn't exist when this preset was saved.
    preset.allColumnKeys = preset.allColumnKeys.filter((k) => k !== "author");
    // Also request a column that no longer exists, to test the "unavailable" warning.
    preset.visibleColumns.push({ key: "raw-DoesNotExist", label: "Ghost Column" });
    localStorage.setItem("markupViz.presets", JSON.stringify(presets));
  });
  await page.evaluate(() => { document.querySelector("#presetSelect").value = ""; });
  await page.select("#presetSelect", "My Preset");
  await new Promise((r) => setTimeout(r, 300));
  status = await page.$eval("#status", (el) => el.textContent);
  const unknownCount = await page.evaluate(() => window.__markupVizState.unknownPresetColumns.size);
  console.log("Status after loading stale preset:", status);
  console.log("unknownPresetColumns size (should be >=1 for 'author'):", unknownCount);

  await page.click("#columnMenuButton");
  await new Promise((r) => setTimeout(r, 150));
  const authorRowIsFlagged = await page.evaluate(() => {
    const rows = [...document.querySelectorAll(".column-menu-row.is-child")];
    const row = rows.find((r) => r.textContent.includes("Author"));
    return row ? row.classList.contains("is-unknown-in-preset") : null;
  });
  console.log("Author row flagged red in column menu:", authorRowIsFlagged);

  // --- Reload the page: last active preset should auto-restore ---
  await page.reload({ waitUntil: "networkidle0" });
  await page.waitForFunction(() => window.__markupVizState && window.__markupVizState.markups.length > 0, { timeout: 20000 });
  await new Promise((r) => setTimeout(r, 300));
  const restoredPresetName = await page.$eval("#presetName", (el) => el.value);
  const restoredStatus = await page.$eval("#status", (el) => el.textContent);
  console.log("Preset name restored after reload:", restoredPresetName);
  console.log("Status after reload (should mention Ghost Column as unavailable):", restoredStatus);

  // --- Delete the preset ---
  await page.select("#presetSelect", "My Preset");
  await page.click("#deletePreset");
  await new Promise((r) => setTimeout(r, 200));
  const presetsAfterDelete = await page.evaluate(() => Object.keys(JSON.parse(localStorage.getItem("markupViz.presets") || "{}")));
  console.log("Presets after delete:", presetsAfterDelete);

  // --- Verify the Google Sheets copy fix: no raw newlines should reach the HTML clipboard cells ---
  const clipboardCheck = await page.evaluate(async () => {
    const markupWithNewline = window.__markupVizState.markups.find((m) => /\n/.test(m.contents || ""));
    return {
      foundMultilineMarkup: Boolean(markupWithNewline),
      sampleContents: markupWithNewline ? markupWithNewline.contents.slice(0, 80) : null,
    };
  });
  console.log("Multiline markup present in sample data:", clipboardCheck.foundMultilineMarkup, clipboardCheck.sampleContents);

  await page.click("#copySheets");
  await new Promise((r) => setTimeout(r, 300));
  const clipboardHtml = await page.evaluate(async () => {
    const items = await navigator.clipboard.read();
    for (const item of items) {
      if (item.types.includes("text/html")) {
        const blob = await item.getType("text/html");
        return await blob.text();
      }
    }
    return null;
  });
  const hasRawNewlineInCell = clipboardHtml ? /<td[^>]*>[^<]*\n/.test(clipboardHtml) : null;
  console.log("Clipboard HTML captured:", Boolean(clipboardHtml));
  console.log("Raw newline found inside a <td> (should be false):", hasRawNewlineInCell);

  console.log("Console/page errors:", errors);

  await browser.close();
})().catch((err) => {
  console.error("TEST FAILED:", err);
  process.exit(1);
});

