  const page = await browser.newPage();
  await page.setDefaultTimeout(20000);
  const errors = [];
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  page.on("console", (msg) => {
    if (msg.type() === "error") errors.push("console.error: " + msg.text());
  });
  page.on("dialog", async (dialog) => {
    console.log("Clipboard permission dialog:", dialog.message());
    await dialog.accept();
  });

  async function waitForStatusSettled() {
    await page.waitForFunction(
      () => !/^(Regenerating|Generating|Loading)/.test(document.querySelector("#status").textContent),
      { timeout: 15000 }
    );
  }

  const context = browser.defaultBrowserContext();
  await context.overridePermissions("http://127.0.0.1:8935", ["clipboard-read", "clipboard-write"]);

  await page.goto("http://127.0.0.1:8935/index.html", { waitUntil: "networkidle0" });
  await page.evaluate(() => localStorage.clear());
