function normalizeCellText(value) {
  return normalizeText(value).replace(/\r\n?/g, "\n").trim();
}

// TSV/CSV convention: a field containing a tab, quote, or newline must be quoted
// (with internal quotes doubled) so the embedded newline stays inside the cell
// instead of a spreadsheet reading it as a new row.
function escapeTsvValue(value) {
  const text = normalizeCellText(value);
  return /[\t"\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

// HTML table equivalent: turn embedded newlines into explicit <br> tags rather than
// leaving raw \n text nodes in the cell, which Google Sheets' HTML paste otherwise
// splits into extra rows.
function cellHtml(value) {
  return escapeHtml(normalizeCellText(value)).replace(/\n/g, "<br>");
}

